PRIVATE_DOCUMENT_SQL = """
CREATE FUNCTION obligations_report_document_private() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.document_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM obligations_document d
         WHERE d.id = NEW.document_id AND d.portal_visible
    ) THEN
        RAISE EXCEPTION 'fiscal-situation report documents must be firm-only'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER obligations_fiscalsituationreport_private_document
    BEFORE INSERT OR UPDATE OF document_id ON obligations_fiscalsituationreport
    FOR EACH ROW EXECUTE FUNCTION obligations_report_document_private();
"""
DROP_PRIVATE_DOCUMENT_SQL = """
DROP TRIGGER IF EXISTS obligations_fiscalsituationreport_private_document
    ON obligations_fiscalsituationreport;
DROP FUNCTION IF EXISTS obligations_report_document_private();
"""


def refuse_reverse_with_rows(
    apps: app_registry.Apps, _editor: BaseDatabaseSchemaEditor
) -> None:
    """Refuse to drop the federal tables once any row exists (plan A11).

    Receipts and payments are provider evidence; recovery is flag off with the
    tables kept (forward repair). Runs as app_migrator (BYPASSRLS), so it counts
    every firm's rows, not the zero a policy would show.
    """
